/**
 * Campaign: invalid-utf8-bytes
 *
 * Exhaustive differential coverage of the surrogateescape path: raw bytes are
 * delivered to both programs through the harness's $'\xNN' quoting, so every
 * byte reaches execve intact.
 *
 * Usage:  node /tmp/dh/invalid-utf8-bytes.mjs [family ...]
 *         node /tmp/dh/invalid-utf8-bytes.mjs --shard I/N [family ...]
 *         node /tmp/dh/invalid-utf8-bytes.mjs --list
 */
import { runSuite, toBuf } from '/tmp/dh/harness.mjs';

const B = (...bytes) => Buffer.from(bytes);
const cat = (...parts) => Buffer.concat(parts.map(toBuf));
const hex = (buf) => [...toBuf(buf)].map((b) => b.toString(16).padStart(2, '0')).join(' ');

/** every byte that can start an invalid sequence */
const HIGH_BYTES = [];
for (let b = 0x80; b <= 0xff; b += 1) HIGH_BYTES.push(b);

/** interesting continuation-byte boundary values (never 0x00 — illegal in argv) */
const BOUNDARY = [0x01, 0x09, 0x22, 0x41, 0x5c, 0x7e, 0x7f, 0x80, 0x8f, 0x90, 0x9f, 0xa0, 0xbf, 0xc0, 0xc2, 0xed, 0xf0, 0xf4, 0xf5, 0xff];

/** valid multi-byte characters, as raw UTF-8 bytes */
const VALID_MB = {
  'U+00E9': B(0xc3, 0xa9),
  'U+0080': B(0xc2, 0x80),
  'U+07FF': B(0xdf, 0xbf),
  'U+0800': B(0xe0, 0xa0, 0x80),
  'U+20AC': B(0xe2, 0x82, 0xac),
  'U+D7FF': B(0xed, 0x9f, 0xbf),
  'U+E000': B(0xee, 0x80, 0x80),
  'U+FFFD': B(0xef, 0xbf, 0xbd),
  'U+FFFF': B(0xef, 0xbf, 0xbf),
  'U+10000': B(0xf0, 0x90, 0x80, 0x80),
  'U+1F600': B(0xf0, 0x9f, 0x98, 0x80),
  'U+10FFFF': B(0xf4, 0x8f, 0xbf, 0xbf),
};

/** JSON-escaping prefixes: each changes the code-point offset differently */
const ESCAPE_PREFIXES = {
  empty: B(),
  ascii1: toBuf('A'),
  ascii2: toBuf('AB'),
  ascii7: toBuf('ABCDEFG'),
  tab: B(0x09), // -> \t   (2 code points)
  nl: B(0x0a), // -> \n
  cr: B(0x0d), // -> \r
  bs: B(0x08), // -> \b
  ff: B(0x0c), // -> \f
  x01: B(0x01), // ->  (6 code points)
  x1f: B(0x1f), // -> 
  x0b: B(0x0b), // ->
  backslash: B(0x5c), // -> \\
  quote: B(0x22), // -> \"
  slash: B(0x2f), // NOT escaped
  del: B(0x7f), // NOT escaped
  mixed: cat(B(0x09), 'x', B(0x01), '\\', '"', B(0x0a)),
  twoMB: cat(VALID_MB['U+20AC'], VALID_MB['U+1F600']),
  mbAndEsc: cat(VALID_MB['U+1F600'], B(0x09), VALID_MB['U+00E9'], B(0x01)),
};

/** deterministic PRNG so fuzz cases are reproducible */
function mulberry32(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const families = {};
const add = (name, fn) => {
  families[name] = fn;
};

// ---------------------------------------------------------------------------
// 1. every single byte 0x80..0xFF alone, in --a / --b / both
// ---------------------------------------------------------------------------
add('single-a', () => HIGH_BYTES.map((b) => ({ argv: ['--a', B(b), '--b', 'x'], label: `a=<${hex(B(b))}>` })));
add('single-b', () => HIGH_BYTES.map((b) => ({ argv: ['--a', 'x', '--b', B(b)], label: `b=<${hex(B(b))}>` })));
add('single-both', () =>
  HIGH_BYTES.map((b) => ({ argv: ['--a', B(b), '--b', B(b)], label: `both=<${hex(B(b))}>` })));
add('single-both-diff', () =>
  HIGH_BYTES.map((b) => ({
    argv: ['--a', B(b), '--b', B(0xff - (b - 0x80))],
    label: `a=<${hex(B(b))}> b=<${hex(B(0xff - (b - 0x80)))}>`,
  })));

// ---------------------------------------------------------------------------
// 2. every single byte, at every prefix length (offsets shift)
// ---------------------------------------------------------------------------
add('single-prefix-ascii', () => {
  const out = [];
  for (const b of HIGH_BYTES) {
    for (const n of [1, 2, 3, 4, 8]) {
      const pre = 'A'.repeat(n);
      out.push({ argv: ['--a', cat(pre, B(b)), '--b', 'z'], label: `a=${pre}<${hex(B(b))}>` });
    }
  }
  return out;
});

add('single-prefix-escapes', () => {
  const out = [];
  for (const b of HIGH_BYTES) {
    for (const [pname, pre] of Object.entries(ESCAPE_PREFIXES)) {
      out.push({ argv: ['--a', cat(pre, B(b)), '--b', 'z'], label: `a=${pname}+<${hex(B(b))}>` });
    }
  }
  return out;
});

// ---------------------------------------------------------------------------
// 3. every single byte preceded by valid multi-byte characters
//    (offsets must be code points, not bytes)
// ---------------------------------------------------------------------------
add('after-multibyte', () => {
  const out = [];
  for (const b of HIGH_BYTES) {
    for (const [cname, ch] of Object.entries(VALID_MB)) {
      out.push({ argv: ['--a', cat(ch, B(b)), '--b', 'z'], label: `a=${cname}+<${hex(B(b))}>` });
    }
  }
  return out;
});

add('after-multibyte-repeat', () => {
  const out = [];
  for (const [cname, ch] of Object.entries(VALID_MB)) {
    for (const n of [1, 2, 3, 5]) {
      for (const b of [0x80, 0x8f, 0xbf, 0xc0, 0xc2, 0xe0, 0xed, 0xf0, 0xf4, 0xf5, 0xfe, 0xff]) {
        const pre = Buffer.concat(Array(n).fill(ch));
        out.push({ argv: ['--a', cat(pre, B(b)), '--b', 'z'], label: `a=${cname}x${n}+<${hex(B(b))}>` });
        out.push({
          argv: ['--a', cat(pre, B(b), ch), '--b', 'z'],
          label: `a=${cname}x${n}+<${hex(B(b))}>+${cname}`,
        });
      }
    }
  }
  return out;
});

