// ---------------------------------------------------------------------------
// 7. named classic malformations (overlong, surrogate, above-max)
// ---------------------------------------------------------------------------
const CLASSIC = {
  'trunc-c2': B(0xc2),
  'trunc-df': B(0xdf),
  'trunc-e0a0': B(0xe0, 0xa0),
  'trunc-e18a': B(0xe1, 0x8a),
  'trunc-efbf': B(0xef, 0xbf),
  'trunc-f09f98': B(0xf0, 0x9f, 0x98),
  'trunc-f09f': B(0xf0, 0x9f),
  'trunc-f0': B(0xf0),
  'trunc-f48fbf': B(0xf4, 0x8f, 0xbf),
  'overlong-c080': B(0xc0, 0x80),
  'overlong-c0af': B(0xc0, 0xaf),
  'overlong-c1bf': B(0xc1, 0xbf),
  'overlong-c181': B(0xc1, 0x81),
  'overlong-e08080': B(0xe0, 0x80, 0x80),
  'overlong-e080af': B(0xe0, 0x80, 0xaf),
  'overlong-e09fbf': B(0xe0, 0x9f, 0xbf),
  'overlong-f0808080': B(0xf0, 0x80, 0x80, 0x80),
  'overlong-f08080af': B(0xf0, 0x80, 0x80, 0xaf),
  'overlong-f08fbfbf': B(0xf0, 0x8f, 0xbf, 0xbf),
