  'overlong-fc80808080 80': B(0xfc, 0x80, 0x80, 0x80, 0x80, 0x80),
  'surr-eda080': B(0xed, 0xa0, 0x80), // U+D800
  'surr-edadbf': B(0xed, 0xad, 0xbf), // U+DB7F
  'surr-edae80': B(0xed, 0xae, 0x80), // U+DB80
  'surr-edbfbf': B(0xed, 0xbf, 0xbf), // U+DFFF
  'surr-edb280': B(0xed, 0xb2, 0x80), // U+DC80
  'cesu8-pair': B(0xed, 0xa0, 0xbd, 0xed, 0xb8, 0x80), // U+D83D U+DE00
  'abovemax-f4908080': B(0xf4, 0x90, 0x80, 0x80), // U+110000
  'abovemax-f4bfbfbf': B(0xf4, 0xbf, 0xbf, 0xbf),
  'abovemax-f5808080': B(0xf5, 0x80, 0x80, 0x80),
  'abovemax-f7bfbfbf': B(0xf7, 0xbf, 0xbf, 0xbf),
