add('runs', () => {
  const out = [];
  for (const byte of [0x80, 0xbf, 0xc0, 0xc2, 0xe0, 0xed, 0xf0, 0xf5, 0xfe, 0xff]) {
    for (let n = 1; n <= 9; n += 1) {
      const run = Buffer.alloc(n, byte);
      out.push({ argv: ['--a', run, '--b', 'z'], label: `a=<${hex(run)}>` });
      out.push({ argv: ['--a', cat('p', run, 'q'), '--b', 'z'], label: `a=p<${hex(run)}>q` });
      out.push({ argv: ['--a', cat('p', run), '--b', 'z'], label: `a=p<${hex(run)}>` });
      out.push({ argv: ['--a', 'z', '--b', cat('p', run, 'q')], label: `b=p<${hex(run)}>q` });
    }
