// ---------------------------------------------------------------------------
// 9. one invalid byte at every index inside a fixed-length string
// ---------------------------------------------------------------------------
add('every-index', () => {
  const out = [];
  const bases = [
    { name: 'ascii8', units: ['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h'].map(toBuf) },
    { name: 'esc8', units: [B(0x09), toBuf('x'), B(0x01), toBuf('\\'), toBuf('"'), B(0x0a), B(0x7f), toBuf('/')] },
    { name: 'mb6', units: [VALID_MB['U+00E9'], VALID_MB['U+20AC'], VALID_MB['U+1F600'], toBuf('A'), VALID_MB['U+FFFF'], VALID_MB['U+10000']] },
    { name: 'mix6', units: [VALID_MB['U+1F600'], B(0x09), VALID_MB['U+00E9'], B(0x01), toBuf('z'), VALID_MB['U+20AC']] },
  ];
  for (const base of bases) {
    for (let pos = 0; pos <= base.units.length; pos += 1) {
      for (const b of [0x80, 0xbf, 0xc0, 0xc2, 0xe0, 0xed, 0xf0, 0xf4, 0xf5, 0xff]) {
        const units = base.units.slice();
        units.splice(pos, 0, B(b));
        out.push({ argv: ['--a', cat(...units), '--b', 'z'], label: `${base.name}@${pos}=<${hex(B(b))}>` });
        out.push({ argv: ['--a', 'z', '--b', cat(...units)], label: `b:${base.name}@${pos}=<${hex(B(b))}>` });
      }
    }
  }
  return out;
});

// ---------------------------------------------------------------------------
// 10. both arguments invalid — first surrogate wins, offsets span the separator
// ---------------------------------------------------------------------------
add('both-invalid', () => {
  const out = [];
  const aVals = [
    B(0xff),
    B(0x80),
    cat('a', B(0xff)),
    cat('ab', B(0xc2)),
    cat(B(0x09), B(0xff)),
    cat(B(0x01), B(0xff)),
    cat(VALID_MB['U+1F600'], B(0xff)),
  ];
  const bVals = [B(0xfe), B(0x80, 0x80), cat('b', B(0xfe)), cat(B(0x01), B(0xfe)), cat(VALID_MB['U+20AC'], B(0xfe))];
  for (const a of aVals) {
    for (const b of bVals) {
      out.push({ argv: ['--a', a, '--b', b], label: `a=<${hex(a)}> b=<${hex(b)}>` });
    }
  }
  return out;
});

add('valid-a-invalid-b-lengths', () => {
  const out = [];
  for (let n = 0; n <= 24; n += 1) {
    const a = 'A'.repeat(n);
    for (const bad of [B(0xff), B(0xff, 0xfe), B(0xc2), B(0xe0, 0xa0), B(0xf0, 0x9f, 0x98)]) {
      out.push({ argv: ['--a', a, '--b', cat('q', bad)], label: `a=A*${n} b=q<${hex(bad)}>` });
      out.push({ argv: ['--a', a, '--b', bad], label: `a=A*${n} b=<${hex(bad)}>` });
    }
