  for (let n = 0; n <= 6; n += 1) {
    for (const unit of [B(0x09), B(0x01), toBuf('\\'), toBuf('"'), VALID_MB['U+20AC'], VALID_MB['U+1F600'], B(0x7f)]) {
      const a = Buffer.concat(Array(n).fill(unit));
      out.push({ argv: ['--a', a, '--b', B(0xff)], label: `a=<${hex(unit)}>*${n} b=ff` });
      out.push({ argv: ['--a', a, '--b', B(0xff, 0xff)], label: `a=<${hex(unit)}>*${n} b=ffff` });
    }
  }
  return out;
});

// ---------------------------------------------------------------------------
// 11. valid bytes mixed with invalid at every position of a multi-byte char
// ---------------------------------------------------------------------------
add('mangled-multibyte', () => {
  const out = [];
  for (const [cname, ch] of Object.entries(VALID_MB)) {
    for (let i = 0; i < ch.length; i += 1) {
      for (const b of [0x41, 0x7f, 0x80, 0xbf, 0xc0, 0xe0, 0xf0, 0xff]) {
        // replace byte i
        const rep = Buffer.from(ch);
        rep[i] = b;
        out.push({ argv: ['--a', rep, '--b', 'z'], label: `${cname} byte${i}:=${b.toString(16)}` });
        // drop byte i
        const drop = cat(ch.subarray(0, i), ch.subarray(i + 1));
        out.push({ argv: ['--a', drop, '--b', 'z'], label: `${cname} drop byte${i}` });
        // insert an extra byte at i
        const ins = cat(ch.subarray(0, i), B(b), ch.subarray(i));
        out.push({ argv: ['--a', ins, '--b', 'z'], label: `${cname} ins ${b.toString(16)}@${i}` });
      }
    }
  }
  return out;
});

// ---------------------------------------------------------------------------
// 12. argparse interaction: invalid bytes in option-looking / extra arguments
// ---------------------------------------------------------------------------
add('argparse-interaction', () => {
  const out = [];
  const bad = [B(0x80), B(0xff), B(0xc2), B(0xed, 0xa0, 0x80), B(0xf5, 0x80)];
  for (const t of bad) {
    out.push({ argv: ['--a', cat('-', t), '--b', 'z'], label: `a=-<${hex(t)}>` });
    out.push({ argv: ['--a', cat('--', t), '--b', 'z'], label: `a=--<${hex(t)}>` });
    out.push({ argv: ['--a=' + '', '--b', 'z'], label: 'a= (empty via =)' });
    out.push({ argv: [cat('--a=', t), '--b', 'z'], label: `--a=<${hex(t)}>` });
    out.push({ argv: [cat('--', t), '--a', 'x', '--b', 'z'], label: `extra --<${hex(t)}>` });
    out.push({ argv: ['--a', 'x', '--b', 'z', t], label: `extra positional <${hex(t)}>` });
    out.push({ argv: ['--a', 'x', '--b', 'z', '--', t], label: `-- then <${hex(t)}>` });
    out.push({ argv: [t], label: `only <${hex(t)}> (missing required)` });
    out.push({ argv: ['--a', 'x', t], label: `missing b + extra <${hex(t)}>` });
    out.push({ argv: [cat('-', t), '--a', 'x', '--b', 'y'], label: `unknown opt -<${hex(t)}>` });
    out.push({ argv: ['--a', 'x', '--b', 'y', '-h', t], label: `-h then <${hex(t)}>` });
    out.push({ argv: [cat('--a', t), 'v', '--b', 'z'], label: `--a<${hex(t)}> v` });
  }
  return out;
});

// ---------------------------------------------------------------------------
// 13. bulk fuzz over random byte strings
// ---------------------------------------------------------------------------
function fuzzCases(seed, count, maxLen, alphabet) {
  const rnd = mulberry32(seed);
  const pick = (arr) => arr[Math.floor(rnd() * arr.length)];
  const out = [];
  for (let i = 0; i < count; i += 1) {
    const mk = () => {
      const n = 1 + Math.floor(rnd() * maxLen);
      const bytes = [];
      for (let k = 0; k < n; k += 1) bytes.push(pick(alphabet));
      return Buffer.from(bytes);
    };
    let a = mk();
    let b = mk();
    // keep argparse out of the picture: values must not look like options
    if (a[0] === 0x2d) a = cat('x', a);
    if (b[0] === 0x2d) b = cat('x', b);
    out.push({ argv: ['--a', a, '--b', b], label: `a=<${hex(a)}> b=<${hex(b)}>` });
  }
  return out;
}

