// ---------------------------------------------------------------------------
// runner
// ---------------------------------------------------------------------------
const argv = process.argv.slice(2);
if (argv[0] === '--list') {
  for (const name of Object.keys(families)) {
    process.stdout.write(`${name}\t${families[name]().length}\n`);
  }
  process.exit(0);
}

let shard = null;
if (argv[0] === '--shard') {
  const [i, n] = argv[1].split('/').map(Number);
  shard = { i, n };
  argv.splice(0, 2);
}

const names = argv.length > 0 ? argv : Object.keys(families);
let total = 0;
let failed = 0;
for (const name of names) {
  if (!families[name]) throw new Error(`unknown family ${name}`);
  let cases = families[name]();
  if (shard) cases = cases.filter((_, idx) => idx % shard.n === shard.i);
  total += cases.length;
  failed += runSuite(name, cases);
}
process.stdout.write(`TOTAL ${total - failed}/${total} passed (${failed} failures)\n`);

